test('get-set/method-conflict/exec.js', async () => {
  const source =
    'class A {\n  get x() {}\n  x() {}\n  set x(_) {}\n}\n\nexpect(Object.getOwnPropertyDescriptors(A.prototype)).toMatchObject({\n  x: {\n    get: undefined,\n    set: expect.any(Function),\n  }\n});\n';
  expect(
    await transformOutcome(source, 'exec.js', {
      transforms: { classes: true },
      helpers: { mode: 'runtime', moduleName: '@babel/runtime', version: '7.29.7' },
    }),
  ).toMatchInlineSnapshot(`
    "var A = (() => {
      'use strict';
      function A() {
        if (!(this instanceof A)) throw new TypeError('Cannot call a class as a function');
      }
      Object.defineProperty(A.prototype, 'x', {
        get: function () {},
        configurable: true,
      });
      Object.defineProperty(A.prototype, 'x', {
        value: function () {},
        writable: true,
        configurable: true,
      });
      Object.defineProperty(A.prototype, 'x', {
        set: function (_) {},
        configurable: true,
      });
      return A;
    })();
    expect(Object.getOwnPropertyDescriptors(A.prototype)).toMatchObject({
      x: {
        get: undefined,
        set: expect.any(Function),
      },
    });"
  `);
});

